    public static class ItaloCalvino
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "A un certo punto era solo questo rapporto a interessarmi, la mia storia diventava soltanto la storia della penna d'oca della monaca che correva sul foglio bianco.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Certe cose sulla vita partigiana nessuno le ha mai dette, nessuno ha mai scritto un racconto che sia anche la storia del sangue nelle vene, delle sostanze nell'organismo.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Che si sia tardato ad ascoltarlo e comprenderlo non fa che provare quant'era in avanti rispetto alla coscienza dei tempi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ci metto molto a iniziare se ho l'idea per un romanzo, trovo ogni scusa possibile per non lavorarci. Una volta iniziato, so essere molto veloce.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il genere umano è una zona del vivente che va definita circoscrivendone i confini.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il luogo ideale per me è quello in cui è più naturale vivere da straniero.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Io sono la pecora nera, l'unico letterato della famiglia.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La prima parte dell'Isola del Tesoro, quando ancora il meccanismo dell'avventura non è scattato, e regna ancora il senso dell'attesa, si può dire sia la più bella.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Lui capì tutto o quasi del nostro mondo, ma sporgendosi da un'estrema ringhiera dell'Ottocento. Noi vediamo il mondo precipitando nella tromba delle scale.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Nell'eros come nella ghiottoneria, il piacere è fatto di precisione.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Nella mia vita ho incontrato donne di grande forza. Non potrei vivere senza una donna al mio fianco. Sono solo un pezzo d'un essere bicefalo e bisessuato, che è il vero organismo biologico e pensante.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Noi le parole di Matteo Salvatore le dobbiamo ancora inventare.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Per il giovane, la donna è quel che sicuramente c'è.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tutto può cambiare, ma non la lingua che ci portiamo dentro, anzi che ci contiene dentro di sé come un mondo più esclusivo e definitivo del ventre materno.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Zig zag tracciato dai cavalli al galoppo e dalle intermittenze del cuore umano.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La vita, pensò il nudo, era un inferno, con rari richiami d'antichi felici paradisi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Così la macchina dell'oppressione sempre si volta contro chi la serve.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "C'era la guerra, e tutti ne eravamo presi, e ormai sapevo che avrebbe deciso delle nostre vite. Della mia vita; e non sapevo come.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La presenza di estranei addormentati suscita negli animi onesti un naturale rispetto, e noi nostro malgrado ne eravamo intimiditi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La prima lezione che potremmo trarre dal libro è che la disobbedienza acquista un senso solo quando diventa una disciplina morale più rigorosa e ardua di quella a cui si ribella.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Le imprese che si basano su di una tenacia interiore devono essere mute e oscure; per poco uno le dichiari o se ne glori, tutto appare fatuo, senza senso o addirittura meschino.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Un gentiluomo [...] è tale stando in terra come stando in cima agli alberi [...] se si comporta rettamente.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Anche quando pare di poche spanne, un viaggio può restare senza ritorno.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il bassotto alzò il muso verso di lui, con lo sguardo dei cani quando non capiscono e non sanno che possono aver ragione a non capire.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Quando ho più idee degli altri, do agli altri queste idee, se le accettano; e questo è comandare.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Chi vuole guardare bene la terra deve tenersi alla distanza necessaria.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ai lutti succedono presto o tardi eventi lieti, è legge della vita.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Si conobbero. Lui conobbe lei e se stesso, perché in verità non s'era mai saputo. E lei conobbe lui e se stessa, perché pur essendosi saputa sempre, mai s'era potuta riconoscere così.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tu ragioni troppo. Perché mai l'amore va ragionato?\n– Per amarti di più. Ogni cosa, a farla ragionando, aumenta il suo potere.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Le imprese più ardite vanno vissute con l'animo più semplice.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Chi sta in alto è ben in vista da ogni parte, [...] mentre c'è chi striscia per nascondere il viso.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "– So che per certe sorta di persone è un punto d'onore tenere la faccia in ombra.\n– Quali, di grazia?\n– Le spie, a dirne una!", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Se alzi un muro, pensa a ciò che resta fuori!", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Viviamo in un paese dove si verificano sempre le cause e non gli effetti.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Si sa che i rivoluzionari sono più formalisti dei conservatori.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La gioventù va via presto sulla terra, figuratevi sugli alberi, donde tutto è destinato a cadere: foglie, frutti.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La forza dell'eremita si misura non da quanto lontano è andato a stare, ma dalla poca distanza che gli basta per staccarsi dalla città, senza mai perderla di vista.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Cosa può sapere del mondo una povera suora?", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tu butti fuori certi peti più puzzolenti dei miei, cadavere. Non so perché tutti ti compiangano. Cosa ti manca? Prima ti muovevi, ora il tuo movimento passa ai vermi che tu nutri.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Così sempre corre il giovane verso la donna: ma è davvero amore per lei a spingerlo? o non è amore soprattutto di sé, ricerca d'una certezza d'esserci che solo la donna gli può dare?", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "A ognuna è data la sua penitenza, qui in convento, il suo modo di guadagnarsi la salvezza eterna. A me è toccata questa di scriver storie: è dura, è dura.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Se infelice è l'innamorato che invoca baci di cui non sa il sapore, mille volte più infelice è chi questo sapore gustò appena e poi gli fu negato.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Anche ad essere si impara...", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La pagina ha il suo bene solo quando la volti e c'è la vita dietro che spinge e scompiglia tutti i fogli del libro. La penna corre spinta dallo stesso piacere che ti fa correre le strade.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "In gioventù ogni libro nuovo che si legge è come un nuovo occhio che si apre e modifica la vista degli altri occhi o libri-occhi che si avevano prima.", Author = "Italo Calvino" },
        };
    }
}